    Point_2 start = *std::min_element(points.begin(), points.end(), 
        [](const Point_2& a, const Point_2& b) {
            if (a.y() != b.y()) return a.y() < b.y();
            return a.x() < b.x();
        });

    // Create a copy of points for sorting
    std::vector<Point_2> sorted_points = points;

    // Sort points by polar angle with respect to the start point
    std::sort(sorted_points.begin(), sorted_points.end(), 
        [&start](const Point_2& a, const Point_2& b) {
            // Calculate cross product to determine orientation
            auto cross = (a.x() - start.x()) * (b.y() - start.y()) - (a.y() - start.y()) * (b.x() - start.x());
            if (cross == 0) {
                // Points are collinear - sort by distance from start
                auto dist_a = (a.x() - start.x()) * (a.x() - start.x()) + (a.y() - start.y()) * (a.y() - start.y());
                auto dist_b = (b.x() - start.x()) * (b.x() - start.x()) + (b.y() - start.y()) * (b.y() - start.y());
                return dist_a < dist_b;
