            return cross > 0;
        });

    // Implement Graham scan algorithm
    std::vector<Point_2> hull;
    if (sorted_points.size() < 3) {
        return sorted_points;
    }

    // Use a stack to build the convex hull
    std::vector<Point_2> stack;
    for (const auto& p : sorted_points) {
        while (stack.size() > 1) {
