                auto dist_b = (b.x() - start.x()) * (b.x() - start.x()) + (b.y() - start.y()) * (b.y() - start.y());
                return dist_a < dist_b;
            }
            return cross > 0;
        });

    // Implement Graham scan algorithm
    std::vector<Point_2> hull;
    if (sorted_points.size() < 3) {
        return sorted_points;
    }

    // Use a stack to build the convex hull
    std::vector<Point_2> stack;
    for (const auto& p : sorted_points) {
        while (stack.size() > 1) {
            // Check orientation using cross product
            auto cross = (stack[stack.size()-2].x() - p.x()) * (stack[stack.size()-1].y() - p.y()) - 
                        (stack[stack.size()-2].y() - p.y()) * (stack[stack.size()-1].x() - p.x());
            if (cross <= 0) {
                stack.pop_back();
            } else {
                break;
            }
        }
        stack.push_back(p);
    }
    hull.push_back(p);

    // Return the computed convex hull
    return hull;
